<?php declare(strict_types=1); namespace Annam; $title = 'Kitchen overview'; $subtitle = date('l, j F') . ' · ' . $store->name(); ?>
<div class="php-stat-grid"><?php foreach ([['Dishes on sale', count(array_filter($items, fn($i) => $i['active']))], ['Hidden / sold out', count(array_filter($items, fn($i) => !$i['active']))], ['Shop items', count(array_filter($items, fn($i) => $i['fulfilment'] === 'courier'))], ['Categories', count($store->categories())]] as [$label,$count]): ?><article class="o-card php-stat"><span><?= e($label) ?></span><strong><?= e($count) ?></strong></article><?php endforeach; ?></div>
<header class="php-section-head"><div><h2>Today’s menu</h2><p class="o-muted">Your meals, dishes and order cutoffs at a glance.</p></div><a class="o-btn" href="/manage/dishes/menu/">Choose dishes →</a></header><div class="php-meal-grid">
<?php foreach ($menus as $meal): ?><section class="o-card php-meal"><header><h3><?= e($meal['slot']['label']) ?></h3><small>Orders close <?= e(substr($meal['slot']['order_cutoff'],0,5)) ?></small></header><?php foreach ($meal['items'] as $item): ?><p><span><?= e($item['name']) ?></span><b><?= money($item['effective_price']) ?></b></p><?php endforeach; ?><?php if (!$meal['items']): ?><p class="o-muted">No dishes selected.</p><?php endif; ?></section><?php endforeach; ?></div>
<section class="o-card"><h2>Keep your kitchen up to date</h2><div class="php-actions"><a class="o-btn o-btn-primary" href="/manage/dishes/new/">+ Add a dish</a><a class="o-btn" href="/manage/banners/new/">New offer banner</a><a class="o-btn" href="/manage/zones/">Delivery areas</a></div></section>
